ther..."]={c=S[58],x=-8241.4,y=590.1,w=S[298],q="Oh Brother...",npc=S[589],k="giver"},["open the maw"]={c=S[58],x=-3779.6,y=-2515.2,w="Wetlands",q="Open the Maw",npc="Deathstalker Agent",k="giver"},["power overwhelming"]={c=S[58],x=-8941,y=1069.6,w=S[298],q="Power Overwhelming",npc="High Sorcerer Andromath",k="giver"},["deviate hides"]={q=S[678],npc="Nalpak",k="dungeon",d=S[663],note="Nalpak stands in the alcove above the cavern entrance; the pin is the dungeon entrance."},["opportunistic education"]={q="Opportunistic Education",npc="Quest giver position unknown",k="dungeon",d="city of dalaran",note="The giver has no known map position, so the pin is the dungeon entrance."},["an unholy alliance"]={c=S[58],x=1286.5,y=334,w="Undercity",q="An Unholy Alliance",npc="Varimathras (turn-in)",k="giver",note="This quest starts from an item drop in Razorfen Downs; the pin is where you hand it in."}},specs={{id="assassination",name=S[84],token="ASSN",title="Assassination | WoW Forever Rogue Field Guide",nav={{id="overview",x=S[597]},{id="journey",x=S[445]},{id="talents",x=S[361]},{id="stats",x=S[478]},{id="combat",x=S[479]},{id="macros",x=S[506]},{id="dungeons",x=S[415]},{id="professions",x=S[446]},{id="crafting",x=S[431]},{id="questgear",x=S[404]},{id=S[356],x=S[560]}},asideNote=S[91],talentString="025303200315510313200330010000000000005",ranks={{tree=S[84],name=S[296],r=2,max=2},{tree=S[84],name="Malice",r=5,max=5},{tree=S[84],name=S[542],r=3,max=3},{tree=S[84],name=S[243],r=3,max=3},{tree=S[84],name="Vigor",r=2,max=2},{tree=S[84],name=S[691],r=3,max=5},{tree=S[84],name="Cold Blood",r=1,max=1},{tree=S[84],name=S[543],r=5,max=5},{tree=S[84],name=S[635],r=5,max=5},{tree=S[84],name="Venom",r=1,max=1},{tree=S[84],name="Seal Fate",r=3,max=3},{tree=S[84],name="Mutilate",r=1,max=1},{tree="Combat",name=S[377],r=3,max=3},{tree="Combat",name=S[321],r=2,max=2},{tree="Combat",name="Deflection",r=3,max=3},{tree="Combat",name="Precision",r=3,max=3},{tree="Combat",name="Riposte",r=1,max=1},{tree="Subtlety",name="Opportunity",r=5,max=5}},order={{l1=10,l2=11,tree=S[84],name=S[296],r1=1,r2=2,max=2},{l1=12,l2=14,tree=S[84],name="Malice",r1=1,r2=3,max=5},{l1=15,l2=17,tree=S[84],name=S[542],r1=1,r2=3,max=3},{l1=18,l2=19,tree=S[84],name="Malice",r1=4,r2=5,max=5},{l1=20,l2=22,tree=S[84],name=S[243],r1=1,r2=3,max=3},{l1=23,l2=24,tree=S[84],name="Vigor",r1=1,r2=2,max=2},{l1=25,l2=25,tree=S[84],name="Cold Blood",r1=1,r2=1,max=1},{l1=26,l2=29,tree=S[84],name=S[543],r1=1,r2=4,max=5},{l1=30,l2=34,tree=S[84],name=S[635],r1=1,r2=5,max=5},{l1=35,l2=35,tree=S[84],name=S[543],r1=5,r2=5,max=5},{l1=36,l2=38,tree=S[84],name="Seal Fate",r1=1,r2=3,max=3},{l1=39,l2=39,tree=S[84],name="Venom",r1=1,r2=1,max=1},{l1=40,l2=40,tree=S[84],name="Mutilate",r1=1,r2=1,max=1},{l1=41,l2=42,tree="Subtlety",name="Opportunity",r1=1,r2=2,max=5},{l1=43,l2=45,tree="Combat",name=S[377],r1=1,r2=3,max=3},{l1=46,l2=47,tree="Combat",name=S[321],r1=1,r2=2,max=2},{l1=48,l2=50,tree="Combat",name="Precision",r1=1,r2=3,max=3},{l1=51,l2=53,tree=S[84],name=S[691],r1=1,r2=3,max=5},{l1=54,l2=56,tree="Combat",name="Deflection",r1=1,r2=3,max=3},{l1=57,l2=57,tree="Combat",name="Riposte",r1=1,r2=1,max=1},{l1=58,l2=60,tree="Subtlety",name="Opportunity",r1=3,r2=5,max=5}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[405]},{t="h1",x=S[84],sub=S[507]},{t="p",s="lede",x="Two daggers and poisons: Mutilate at 40 hits with both weapons for two combo points, Seal Fate turns critical strikes into extra points, and Venom makes Shank boost your poisons."},{t="pills",list={S[411],"Daggers, poisons and burst",S[447]}},{t="anchor",id="journey"},{t="kicker",x=S[598]},{t="h2",x=S[329]},{t="p",x="These stages follow the talent order below. Leveling is slower before 40; Mutilate is the big power spike, and it needs a dagger in each hand."},{t="p",s="level",x="10–25 · Critical strikes and combo points"},{t="p",x="Remorseless Attacks 2/2 (10–11) gives your next builder 40% more critical chance after a kill. Malice reaches 5/5 by 19 for 5% critical chance on attacks and poisons, Ruthlessness 3/3 (15–17) gives finishers a 60% chance to add a combo point, Improved Slice and Dice 3/3 (20–22) lengthens Slice and Dice, Vigor 2/2 (23–24) adds 10 maximum Energy, and Cold Blood arrives at 25."},{t="p",s="level",x="26–40 · Poisons, Seal Fate and Mutilate"},{t="p",x="Improved Poisons 5/5 (26–29 and 35) makes your poisons apply more often, Relentless Strikes 5/5 (30–34) gives each combo point you spend a 20% chance to restore 25 Energy, and Seal Fate 3/3 (36–38) gives builder critical strikes a 100% chance to add a combo point. Venom at 39 makes Shank (trained at 24) raise your poison damage by 30% and poison chance by 20% for 6 seconds, and Mutilate at 40 strikes with both daggers for two combo points."},{t="p",s="level",x="41–60 · Combat and Subtlety support"},{t="p",x="Opportunity 5/5 (41–42 and 58–60) adds 20% to Backstab, Garrote, Ambush and Mutilate, Coup de Grace 3/3 (43–45) adds 20% Eviscerate damage, Efficient Strikes 2/2 (46–47) makes Sinister Strike and Hemorrhage cheaper, Precision 3/3 (48–50) adds hit, Vile Poisons 3/5 (51–53) adds poison damage, and Deflection 3/3 (54–56) with Riposte at 57 adds parry chance and a counterattack."},{t="anchor",id="talents"},{t="kicker",x=S[362]},{t="h2",x=S[411]},{t="p",x=S[64]},{t="widget",w="talents"},{t="h4",s="summary",x=S[416]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[344]},{t="p",x=S[117]},{t="widget",w="order"},{t="p",s="notice",x="Mutilate needs a dagger in both hands, and some enemies are immune to poisons, which lowers this build’s damage against them. Keep Shank on cooldown once Venom is learned: it is cheap, cannot miss, generates Energy and powers up your poisons."},{t="anchor",id="stats"},{t="kicker",x=S[480]},{t="h2",x=S[385]},{t="p",x="Assassination needs a dagger in each hand for Mutilate. Expertise and hit come first so your attacks land, then Agility, weapon damage and critical strike."},{t="h3",x=S[578]},{t="stat",i=1,b=S[439],x="daggers, high top-end damage"},{t="stat",i=2,b="Agility",x=S[357]},{t="stat",i=3,b="Stamina",x=""},{t="stat",i=4,b="Strength",x=S[636]},{t="p",s="small",x="Mutilate arrives at 40 and needs two daggers, so keep daggers in mind before then."},{t="h3",x="At level 60"},{t="stat",i=1,b="Expertise",x="to 6.5%"},{t="stat",i=2,b="Hit chance",x="to 8%"},{t="stat",i=3,b="Agility",x=""},{t="stat",i=4,b=S[439],x=""},{t="stat",i=5,b=S[664],x=""},{t="p",s="small",x=S[186]},{t="p",s="notice",x=S[49]},{t="anchor",id="combat"},{t="kicker",x=S[386]},{t="h2",x=S[432]},{t="p",x="Treat this as a priority list, not a fixed loop. Leave out what you have not learned yet: poisons at 20, Shank at 24, Cheap Shot at 26, Venom at 39 and Mutilate at 40 in this order."},{t="h4",x="Poisons before combat"},{t="p",x="From 20, after the poison quest, keep Instant Poison on both weapons; use Crippling Poison against enemies that run away. In Forever a poison can share a weapon with a sharpening stone, and poisons have more charges."},{t="h4",x="Open from Stealth"},{t="p",x="Cheap Shot (26) stuns the enemy and prevents a lot of damage; Garrote opens for damage. Ambush also works with a dagger in your main hand from behind."},{t="h4",x=S[481]},{t="p",x="Backstab from behind, Sinister Strike from the front, and Mutilate from 40 with a dagger in each hand. Mutilate strikes with both daggers, deals more damage to poisoned targets and awards two combo points."},{t="h4",x="Spend combo points"},{t="p",x="Keep Slice and Dice up when there are enemies to hit for its duration; otherwise Eviscerate at five combo points. From 39, use Shank on cooldown so Venom keeps your poisons stronger. Cold Blood guarantees a critical Mutilate or Eviscerate."},{t="h4",x="Energy"},{t="p",x="Energy regenerates continuously at about 10 per second. Pool it before a burst if needed, but never sit at full Energy. Relentless Strikes and Seal Fate refund Energy and points."},{t="h4",x="Defense and control"},{t="p",x="Evasion early and often while solo, Gouge or Blind to stop an enemy and bandage, Kidney Shot to stun with combo points, Kick to interrupt. Rogues have no area damage, so pick targets one at a time."},{t="abil",names={"Mutilate","Venom",S[579],"Eviscerate","Cold Blood","Cheap Shot","Garrote","Evasion","Instant Poison"}},{t="h3",x=S[464]},{t="p",x="Priority for Assassination: dagger weapon damage first (high top-end damage benefits Mutilate), then hit, Agility, critical strike, Strength and Stamina. You need two daggers to use Mutilate."},{t="p",x="Blade of Cunning, a dagger from the race-specific class quest available at your trainer from level 10, is your first big weapon upgrade. Rogues use leather armor, daggers, one-handed swords, axes (new for Rogues in Forever), maces and fist weapons, plus bows, guns, crossbows and thrown weapons."},{t="h3",x=S[387]},{t="p",x="Start the poison quest at 20: Alliance from Master Mathias Shaw in Stormwind (Klaven’s Tower in Westfall, 70 Lockpicking), Horde from Shenthul in Orgrimmar (the Venture Co. tower in the Barrens, 80 Lockpicking). Pick Pocket the tower key before opening the chest, since the Touch of Zanzil blocks Stealth."},{t="p",x="Rogues cannot heal themselves: level First Aid for bandages, carry food and potions, and use campfires. Thistle Tea (Cooking 60, recipe from the poison quest) restores 100 Energy once every 5 minutes."},{t="anchor",id="macros"},{t="kicker",x=S[508]},{t="h2",x=S[307]},{t="p",x=S[61]},{t="p",s="notice",x=S[53]},{t="macro",n=S[345],x=S[201],code=S[276]},{t="macro",n=S[358],x=S[143],code=S[233]},{t="macro",n=S[580],x=S[189],code=S[219]},{t="macro",n=S[561],x=S[127],code=S[203]},{t="macro",n=S[599],x=S[155],code=S[206]},{t="macro",n=S[562],x=S[139],code=S[218]},{t="macro",n="Vanish",x=S[181],code=S[278]},{t="macro",n=S[417],x=S[137],code=S[269]},{t="macro",n=S[330],x=S[157],code=S[241]},{t="macro",n="Mutilate with auto-attack",x="Starts auto-attack and uses Mutilate. Needs a dagger in each hand.",code="#showtooltip Mutilate\n/startattack [harm,nodead]\n/cast [harm,nodead] Mutilate"},{t="macro",n="Ambush in Stealth, Mutilate in combat",x="One button: opens with Ambush from Stealth, then builds combo points with Mutilate. Auto-attack starts only once you leave Stealth.",code="#showtooltip\n/startattack [nostealth,harm,nodead]\n/cast [stealth,harm,nodead] Ambush; [harm,nodead] Mutilate"},{t="macro",n="Shank with auto-attack",x="Starts auto-attack and uses Shank (from 24). With Venom, every Shank also raises your poison damage and poison chance for 6 seconds.",code="#showtooltip Shank\n/startattack\n/cast Shank"},{t="macro",n=S[527],x="Activates Cold Blood, then Eviscerates for a guaranteed critical strike. Use it at five combo points. Not tested in game.",code=S[297]},{t="p",s="small",x=S[220]},{t="anchor",id="dungeons"},{t="kicker",x=S[563]},{t="h2",x=S[346]},{t="p",x=S[69]},{t="widget",w="rarity"},{t="p",s="notice",x=S[70]},{t="p",s="notice",x=S[35]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[388]},{t="h2",x=S[343]},{t="p",x=S[83]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[418]},{t="h2",x=S[331]},{t="p",x=S[32]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[389]},{t="h2",x=S[303]},{t="p",x=S[28]},{t="widget",w="quest"},{t="anchor",id=S[356]},{t="kicker",x=S[564]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[104]}},dungeons={{n=S[282],lr="13–18",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={},t={},no={S[20],S[66],S[12]}}},{n=S[247],lr="13–18",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={},t={},no={S[20],S[66],S[12]}}},{n=S[242],lr="15–20",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={{n=S[509],st=S[30],no=S[37],it={}}},t={},no={S[36],S[23],S[12]}}},{n=S[222],lr="17–24",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={{n=S[448],st=S[30],no=S[37],it={}}},t={{id=10413,n=S[339],mob=S[510],st=S[212],no=S[103]}},no={S[36],S[66],S[12]}}},{n=S[194],lr="17–26",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={{n=S[483