3],mob=S[88],st=S[195],no=S[92]}},no={S[20],S[23],S[12]}}},{n=S[544],lr="35–40",st=S[72],no=S[18],ba=false},{n=S[379],lr="36–44",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={},t={{id=2262,n=S[246],mob=S[17],st=S[22],no=S[9]},{id=5756,n="Sliverblade",mob=S[17],st=S[22],no=S[9]},{id=7755,n=S[223],mob=S[88],st=S[195],no=S[92]}},no={S[20],S[23],S[12]}}},{n=S[324],lr="37–46",st=S[41],no=S[62],ba=true,ra={ck=S[65],r={{n="Ragglesnout",st=S[199],no=S[46],it={}},{n=S[545],st=S[277],no=S[46],it={}}},t={},no={S[20],S[23],S[12]}}},{n=S[347],lr="38–46",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={},t={{id=2262,n=S[246],mob=S[17],st=S[22],no=S[9]},{id=5756,n="Sliverblade",mob=S[17],st=S[22],no=S[9]},{id=7755,n=S[223],mob=S[88],st=S[195],no=S[92]}},no={S[20],S[23],S[12]}}},{n=S[466],lr="40–45",st=S[72],no=S[18],ba=false},{n="Uldaman",lr="41–51",st=S[41],no=S[63],ba=true,ra={ck=S[65],r={{n=S[419],st=S[348],no=S[129],it={}}},t={{id=9426,n=S[467],mob=S[17],st=S[22],no=S[9]}},no={S[20],S[23],S[12]}}},{n="Zul'Farrak",lr="44–54",st=S[72],no=S[18],ba=false},{n="Maraudon",lr="46–55",st=S[72],no=S[18],ba=false},{n=S[638],lr="48–53",st=S[72],no=S[18],ba=false},{n=S[390],lr="50–60",st=S[72],no=S[18],ba=false},{n=S[546],lr="52–60",st=S[72],no=S[18],ba=false},{n="Dire Maul",lr="54–60",st=S[72],no=S[148],ba=false},{n=S[284],lr="55–60",st=S[72],no=S[18],ba=false},{n=S[600],lr="55–60",st=S[72],no=S[18],ba=false},{n="Scholomance",lr="58–60",st=S[72],no=S[18],ba=false},{n="Stratholme",lr="58–60",st=S[72],no=S[18],ba=false},{n=S[547],lr="58–60",st=S[72],no=S[18],ba=false},{n=S[449],lr="59–60",st=S[72],no=S[18],ba=false}}},{id="combat",name="Combat",token="COMBAT",title="Combat | WoW Forever Rogue Field Guide",nav={{id="overview",x=S[597]},{id="journey",x=S[445]},{id="talents",x=S[361]},{id="stats",x=S[478]},{id="combat",x=S[479]},{id="macros",x=S[506]},{id="dungeons",x=S[415]},{id="professions",x=S[446]},{id="crafting",x=S[431]},{id="questgear",x=S[404]},{id=S[356],x=S[560]}},asideNote=S[91],talentString="025303012010000003200330212010321551",ranks={{tree=S[84],name=S[296],r=2,max=2},{tree=S[84],name="Malice",r=5,max=5},{tree=S[84],name=S[542],r=3,max=3},{tree=S[84],name=S[243],r=3,max=3},{tree=S[84],name=S[672],r=1,max=1},{tree=S[84],name="Lethality",r=2,max=2},{tree=S[84],name="Cold Blood",r=1,max=1},{tree="Combat",name=S[377],r=3,max=3},{tree="Combat",name=S[321],r=2,max=2},{tree="Combat",name="Deflection",r=3,max=3},{tree="Combat",name="Precision",r=3,max=3},{tree="Combat",name="Endurance",r=2,max=2},{tree="Combat",name="Riposte",r=1,max=1},{tree="Combat",name="Composure",r=2,max=2},{tree="Combat",name=S[639],r=1,max=1},{tree="Combat",name="Aggression",r=3,max=3},{tree="Combat",name=S[528],r=2,max=2},{tree="Combat",name=S[640],r=1,max=1},{tree="Combat",name=S[581],r=5,max=5},{tree="Combat",name=S[673],r=5,max=5},{tree="Combat",name=S[455],r=1,max=1}},order={{l1=10,l2=11,tree="Combat",name=S[321],r1=1,r2=2,max=2},{l1=12,l2=13,tree=S[84],name=S[296],r1=1,r2=2,max=2},{l1=14,l2=16,tree="Combat",name=S[377],r1=1,r2=3,max=3},{l1=17,l2=18,tree="Combat",name="Precision",r1=1,r2=2,max=3},{l1=19,l2=21,tree="Combat",name="Deflection",r1=1,r2=3,max=3},{l1=22,l2=22,tree="Combat",name="Riposte",r1=1,r2=1,max=1},{l1=23,l2=24,tree="Combat",name="Endurance",r1=1,r2=2,max=2},{l1=25,l2=25,tree="Combat",name="Precision",r1=3,r2=3,max=3},{l1=26,l2=26,tree="Combat",name="Composure",r1=1,r2=1,max=2},{l1=27,l2=27,tree="Combat",name=S[639],r1=1,r2=1,max=1},{l1=28,l2=30,tree="Combat",name="Aggression",r1=1,r2=3,max=3},{l1=31,l2=31,tree="Combat",name="Composure",r1=2,r2=2,max=2},{l1=32,l2=32,tree="Combat",name=S[640],r1=1,r2=1,max=1},{l1=33,l2=34,tree="Combat",name=S[528],r1=1,r2=2,max=2},{l1=35,l2=37,tree="Combat",name=S[581],r1=1,r2=3,max=5},{l1=38,l2=42,tree="Combat",name=S[673],r1=1,r2=5,max=5},{l1=43,l2=43,tree="Combat",name=S[455],r1=1,r2=1,max=1},{l1=44,l2=46,tree=S[84],name="Malice",r1=1,r2=3,max=5},{l1=47,l2=49,tree=S[84],name=S[542],r1=1,r2=3,max=3},{l1=50,l2=51,tree=S[84],name="Malice",r1=4,r2=5,max=5},{l1=52,l2=53,tree=S[84],name="Lethality",r1=1,r2=2,max=2},{l1=54,l2=54,tree=S[84],name=S[672],r1=1,r2=1,max=1},{l1=55,l2=56,tree=S[84],name=S[243],r1=1,r2=2,max=3},{l1=57,l2=57,tree=S[84],name="Cold Blood",r1=1,r2=1,max=1},{l1=58,l2=59,tree="Combat",name=S[581],r1=4,r2=5,max=5},{l1=60,l2=60,tree=S[84],name=S[243],r1=3,r2=3,max=3}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[405]},{t="h1",x="Combat",sub=S[507]},{t="p",s="lede",x="Cheap, steady weapon strikes: Sinister Strike and Eviscerate from the front, Riposte after a parry, Blade Flurry to hit a second enemy, and Adrenaline Rush at 43 to double your Energy."},{t="pills",list={S[559],"Recommended leveling build",S[447]}},{t="anchor",id="journey"},{t="kicker",x=S[598]},{t="h2",x=S[329]},{t="p",x="These stages follow the talent order below, a Combat build that works for leveling a Rogue from 1 to 60. It needs no Stealth and no position behind the target."},{t="p",s="level",x="10–21 · Cheaper strikes"},{t="p",x="Efficient Strikes 2/2 (10–11) makes Sinister Strike and Hemorrhage 5 Energy cheaper and Remorseless Attacks 2/2 (12–13) adds critical chance after kills. Coup de Grace 3/3 (14–16) adds 20% Eviscerate damage, Precision 2/3 (17–18) adds hit, and Deflection 3/3 (19–21) gives 6% parry chance for Riposte."},{t="p",s="level",x="22–32 · Riposte and Blade Flurry"},{t="p",x="Riposte at 22 strikes for 150% weapon damage and disarms for 6 seconds after you parry. Endurance 2/2 (23–24) shortens Sprint and Evasion by 60%, Precision reaches 3/3 at 25, Composure (26 and 31) makes Poised 10 Energy cheaper, Flawless Execution at 27 makes Eviscerate cost 15 less, Aggression 3/3 (28–30) adds 15% to Sinister Strike and Eviscerate, and Blade Flurry at 32 gives 20% attack speed and a second target for 15 seconds."},{t="p",s="level",x="33–60 · Hack and Slash and Adrenaline Rush"},{t="p",x="Dual Wield Specialization 2/2 (33–34) adds 50% off-hand damage, Hack and Slash 3/5 (35–37) gives your weapon type a bonus, Flash of Steel 5/5 (38–42) makes Shank generate 15 more Energy and cuts its cooldown by 2 seconds, and Adrenaline Rush at 43 doubles Energy regeneration for 15 seconds. The last points go into Assassination: Malice (44–46 and 50–51), Ruthlessness (47–49), Lethality 2/2 (52–53), Blood Splatter at 54, Improved Slice and Dice (55–56 and 60) and Cold Blood at 57, with Hack and Slash completed at 58–59."},{t="anchor",id="talents"},{t="kicker",x=S[362]},{t="h2",x=S[559]},{t="p",x=S[64]},{t="widget",w="talents"},{t="h4",s="summary",x=S[416]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[344]},{t="p",x=S[117]},{t="widget",w="order"},{t="p",s="notice",x="Hack and Slash works with whatever weapon you hold: at 5/5, swords and axes have a 5% chance for an extra attack, daggers and fist weapons gain 5% critical strike chance, and maces ignore 15% of armor. Restless Blades is not in the Forever Combat tree; Flawless Execution takes its place."},{t="anchor",id="stats"},{t="kicker",x=S[480]},{t="h2",x=S[385]},{t="p",x="Combat lives on its main-hand weapon: your auto attacks and most abilities scale with it. Expertise and hit come first, then Agility."},{t="h3",x=S[578]},{t="stat",i=1,b="Main-hand weapon damage",x="a slow weapon"},{t="stat",i=2,b="Agility",x=S[357]},{t="stat",i=3,b="Stamina",x=""},{t="stat",i=4,b="Strength",x=S[636]},{t="p",s="small",x="Dual wielding misses often, so hit on leveling gear is worth more than it looks."},{t="h3",x="At level 60"},{t="stat",i=1,b="Expertise",x="to 6.5%"},{t="stat",i=2,b="Hit chance",x="to 8%"},{t="stat",i=3,b="Agility",x=""},{t="stat",i=4,b=S[439],x=""},{t="stat",i=5,b=S[664],x=""},{t="p",s="small",x=S[186]},{t="p",s="notice",x=S[49]},{t="anchor",id="combat"},{t="kicker",x=S[386]},{t="h2",x=S[432]},{t="p",x="Treat this as a priority list, not a fixed loop. Kick arrives at 12, Riposte at 22, Shank at 24, Blade Flurry at 32 and Adrenaline Rush at 43 in this order. Use Shank on cooldown: it is cheap, cannot miss and generates Energy, more with Flash of Steel."},{t="h4",x="Before the pull"},{t="p",x="Sap an extra Humanoid from Stealth (in Forever it no longer breaks Stealth), and keep Blade Flurry off when a sapped enemy is close. From 20 keep Instant Poison on both weapons."},{t="h4",x=S[481]},{t="p",x="Start with Sinister Strike; your main hand should be a slow weapon with high damage. Combo points stay on your previous target in Forever if you switch."},{t="h4",x="Interrupts and Riposte"},{t="p",x="Kick (12) interrupts heals and dangerous casts. After a parry, use Riposte for 150% weapon damage and a 6-second disarm."},{t="h4",x="Finishers"},{t="p",x="Slice and Dice at one or two combo points on enemies that take longer to kill or when moving straight to the next target; Eviscerate at four or five combo points or to finish. Cold Blood before a five-point Eviscerate guarantees a critical strike."},{t="h4",x="Two enemies"},{t="p",x="Evasion against heavy melee damage, Blade Flurry when two enemies are in melee range, focus one target while Blade Flurry hits the other. Blade Flurry also raises attack speed on a single tough target."},{t="h4",x=S[455]},{t="p",x="Use it after spending some Energy so the faster regeneration is not wasted, and combine it with Blade Flurry for tough two-enemy pulls."},{t="abil",names={"Sinister Strike",S[579],"Eviscerate","Riposte",S[640],S[455],"Kick","Evasion","Cold Blood"}},{t="h3",x=S[464]},{t="p",x="Use a slow main-hand weapon with high damage for Sinister Strike, and compare damage per second and stats for the off hand. Swords, axes and maces suit this build; daggers work well in the off hand. A later weapon is not always better than the one you have."},{t="p",x="Stats for Rogues: weapon damage, hit (dual wielding misses often), Agility, attack power and critical strike, with Strength and Stamina as a bonus. Learn one-handed axes at a weapon master if you want them."},{t="h3",x=S[387]},{t="p",x="Start the poison quest at 20 (Alliance: Master Mathias Shaw, Stormwind; Horde: Shenthul, Orgrimmar). Bring a main-hand dagger for Ambush, especially as Horde, and raise Lockpicking to 70 (Alliance) or 80 (Horde) first. Learn Pick Lock at 16 and keep Thieves’ Tools in your bags."},{t="p",x="Take Mining and Blacksmithing at the start for Rough Sharpening Stones and Weightstones, or buying them. Level First Aid; Blind or Gouge an enemy and bandage while it is controlled."},{t="anchor",id="macros"},{t="kicker",x=S[508]},{t="h2",x=S[307]},{t="p",x=S[61]},{t="p",s="notice",x=S[53]},{t="macro",n=S[345],x=S[201],code=S[276]},{t="macro",n=S[358],x=S[143],code=S[233]},{t="macro",n=S[580],x=S[189],code=S[219]},{t="macro",n=S[561],x=S[127],code=S[203]},{t="macro",n=S[599],x=S[155],code=S[206]},{t="macro",n=S[562],x=S[139],code=S[218]},{t="macro",n="Vanish",x=S[181],code=S[278]},{t="macro",n=S[417],x=S[137],code=S[269]},{t="macro",n=S[330],x=S[157],code=S[241]},{t="macro",n="Sinister Strike with auto-attack",x="Starts auto-attack and uses Sinister Strike when you have the Energy.",code="#showtooltip Sinister Strike\n/startattack [harm,nodead]\n/cast Sinister Strike"},{t="macro",n="Riposte with auto-attack",x="Use after a parry for 150% weapon damage and a 6-second disarm. Not tested in game.",code="#showtooltip Riposte\n/startattack [harm,nodead]\n/cast [harm,nodead] Riposte"},{t="macro",n=S[527],x="Activates Cold Blood, then Eviscerates for a guaranteed critical strike; use it at five combo points. Not tested in game.",code=S[297]},{t="macro",n="Mind-numbing Poison on your off hand",x="Applies the poison to weapon slot 17. Change the name to Instant Poison or another rank as needed.",code="#showtooltip Mind-numbing Poison\n/use Mind-numbing Poison\n/use 17"},{t="p",s="small",x=S[220]},{t="anchor",id="dungeons"},{t="kicker",x=S[563]},{t="h2",x=S[346]},{t="p",x=S[69]},{t="widget",w="rarity"},{t="p",s="notice",x=S[70]},{t="p",s="notice",x=S[35]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[388]},{t="h2",x=S[343]},{t="p",x=S[83]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[418]},{t="h2",x=S[331]},{t="p",x=S[32]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[389]},{t="h2",x=S[303]},{t="p",x=S[28]},{t="widget",w="quest"},{t="anchor",id=S[356]},{t="kicker",x=S[564]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[104]}},dungeons={{n=S[282],lr="13–18",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={},t={},no={S[20],S[66],S[12]}}},{n=S[247],lr="13–18",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={},t={},no={S[20],S[66],S[12]}}},{n=S[242],lr="15–20",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={{n=S[509],st=S[30],no=S[37],it={}}},t={},no={S[36],S[23],S[12]}}},{n=S[222],lr="17–24",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={{n=S[448],st=S[30],no=S[37],it={}}},t={{id=10413,n=S[339],mob=S[510],st=S[212],no=S[103]}},no={S[36],S[66],S[12]}}},{n=S[194],lr="17–26",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={{n=S[483],st=S[30],no=S[109],it={{id=5444,n=S[529]}}}},t={{id=1951,n=S[470],mob=S[17],st=S[22],no=S[9]}},no={S[36],S[23],S[12]}}},{n=S[196],lr="22–30",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={{n=S[482],st=S[30],no=S[37],it={}},{n="Gefell",st=S[30],no=S[37],it={}},{n="Gemela",st=S[30],no=S[37],it={}}},t={{id=1482,n="Shadowfang",mob=S[17],st=S[22],no=S[9]},{id=1483,n=S[622],mob=S[17],st=S[22],no=S[9]},{id=1935,n=S[441],mob=S[17],st=S[22],no=S[9]},{id=2807,n=S[571],mob=S[17],st=S[22],no=S[9]}},no={S[36],S[23],S[12]}}},{n=S[302],lr="24–32",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={{n=S[381],st=S[30],no=S[109],it={{id=2941,n=S[531]}}}},t={{id=1076,n=S[322],mob=S[17],st=S[22],no=S[9]},{id=274092,n=S[420],mob=S[17],st=S[378],no=S[9]}},no={S[36],S[23],S[12]}}},{n=S[197],lr="24–32",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={},t={{id=1454,n=S[458],mob=S[17],st=S[22],no=S[9]},{id=1491,n=S[421],mob=S[17],st=S[22],no=S[153]}},no={S[20],S[23],S[12]}}},{n=S[254],lr="26–31",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={},t={},no={S[20],S[66],S[12]}}},{n=S[286],lr="28–3