ax=2},{tree="Combat",name="Deflection",r=3,max=3},{tree="Combat",name="Precision",r=3,max=3},{tree="Combat",name="Riposte",r=1,max=1},{tree="Combat",name="Composure",r=2,max=2},{tree="Subtlety",name="Setup",r=3,max=3},{tree="Subtlety",name="Opportunity",r=5,max=5},{tree="Subtlety",name="Dirty Deeds",r=2,max=2},{tree="Subtlety",name="Camouflage",r=1,max=3},{tree="Subtlety",name="Initiative",r=3,max=3},{tree="Subtlety",name=S[601],r=1,max=1},{tree="Subtlety",name=S[665],r=3,max=3},{tree="Subtlety",name="Elusiveness",r=2,max=2},{tree="Subtlety",name=S[674],r=1,max=1},{tree="Subtlety",name=S[651],r=2,max=2},{tree="Subtlety",name="Preparation",r=1,max=1},{tree="Subtlety",name="Hemorrhage",r=1,max=1},{tree="Subtlety",name="Boot Knife",r=5,max=5},{tree="Subtlety",name="Death Mark",r=1,max=1}},order={{l1=10,l2=14,tree="Subtlety",name="Opportunity",r1=1,r2=5,max=5},{l1=15,l2=15,tree="Subtlety",name="Camouflage",r1=1,r2=1,max=3},{l1=16,l2=17,tree="Subtlety",name="Setup",r1=1,r2=2,max=3},{l1=18,l2=19,tree="Subtlety",name="Dirty Deeds",r1=1,r2=2,max=2},{l1=20,l2=20,tree="Subtlety",name="Setup",r1=3,r2=3,max=3},{l1=21,l2=23,tree="Subtlety",name="Initiative",r1=1,r2=3,max=3},{l1=24,l2=24,tree="Subtlety",name=S[601],r1=1,r2=1,max=1},{l1=25,l2=25,tree="Subtlety",name=S[674],r1=1,r2=1,max=1},{l1=26,l2=28,tree="Subtlety",name=S[665],r1=1,r2=3,max=3},{l1=29,l2=29,tree="Subtlety",name="Elusiveness",r1=1,r2=1,max=2},{l1=30,l2=30,tree="Subtlety",name="Hemorrhage",r1=1,r2=1,max=1},{l1=31,l2=31,tree="Subtlety",name="Preparation",r1=1,r2=1,max=1},{l1=32,l2=32,tree="Subtlety",name="Elusiveness",r1=2,r2=2,max=2},{l1=33,l2=34,tree=S[84],name=S[296],r1=1,r2=2,max=2},{l1=35,l2=37,tree=S[84],name="Malice",r1=1,r2=3,max=5},{l1=38,l2=38,tree=S[84],name=S[243],r1=1,r2=1,max=3},{l1=39,l2=41,tree="Combat",name=S[377],r1=1,r2=3,max=3},{l1=42,l2=43,tree="Combat",name=S[321],r1=1,r2=2,max=2},{l1=44,l2=46,tree="Combat",name="Precision",r1=1,r2=3,max=3},{l1=47,l2=48,tree="Subtlety",name=S[651],r1=1,r2=2,max=2},{l1=49,l2=53,tree="Subtlety",name="Boot Knife",r1=1,r2=5,max=5},{l1=54,l2=54,tree="Subtlety",name="Death Mark",r1=1,r2=1,max=1},{l1=55,l2=57,tree="Combat",name="Deflection",r1=1,r2=3,max=3},{l1=58,l2=58,tree="Combat",name="Riposte",r1=1,r2=1,max=1},{l1=59,l2=60,tree="Combat",name="Composure",r1=1,r2=2,max=2}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[405]},{t="h1",x="Subtlety",sub=S[507]},{t="p",s="lede",x="Stealth openers and bleeds: Premeditation and Initiative for early combo points, Hemorrhage at 30 as a cheap builder that boosts Rupture and Garrote, and Boot Knife and Death Mark for burst from 49."},{t="pills",list={S[412],"Stealth openers and control",S[447]}},{t="anchor",id="journey"},{t="kicker",x=S[598]},{t="h2",x=S[329]},{t="p",x="These stages follow the talent order below. The first 20 points race to Hemorrhage at 30; You can play another build until then and respec at 30."},{t="p",s="level",x="10–20 · Stealth openers"},{t="p",x="Opportunity 5/5 (10–14) adds 20% to Backstab, Garrote, Ambush and Mutilate, and Camouflage at 15 moves you faster in Stealth. Setup 3/3 (16–17 and 20) can add a combo point when you dodge, and Dirty Deeds 2/2 (18–19) makes your openers cheaper. Ambush is trained at 18."},{t="p",s="level",x="21–32 · Hemorrhage at 30"},{t="p",x="Initiative 3/3 (21–23) adds a combo point to Ambush, Garrote and Cheap Shot, Premeditation at 24 adds two combo points before you open, Ghostly Strike at 25 adds dodge chance and lets your next Ambush or Garrote be used without Stealth, and Serrated Blades 3/3 (26–28) lets you ignore 9% of armor. Hemorrhage at 30 is a cheap builder that makes your Rupture and Garrote deal 15% more damage, Preparation at 31 resets Evasion, Vanish and your other cooldowns, and Elusiveness 2/2 (29 and 32) shortens Vanish and Blind."},{t="p",s="level",x="33–60 · Boot Knife, Death Mark and support"},{t="p",x="Remorseless Attacks (33–34), Malice 3/5 (35–37) and Improved Slice and Dice (38) come from Assassination, then Coup de Grace 3/3 (39–41), Efficient Strikes 2/2 (42–43) and Precision 3/3 (44–46) from Combat. Heightened Senses 2/2 (47–48), Boot Knife 5/5 (49–53), which gives Shank a 100% chance to add 2 combo points, and Death Mark at 54 finish the Subtlety tree. Death Mark is a finisher that stores part of your damage for 6 seconds, Garrote and Rupture at twice the rate, then deals it. Deflection 3/3 (55–57), Riposte at 58 and Composure 2/2 (59–60) finish the build."},{t="anchor",id="talents"},{t="kicker",x=S[362]},{t="h2",x=S[412]},{t="p",x=S[64]},{t="widget",w="talents"},{t="h4",s="summary",x=S[416]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[344]},{t="p",x=S[117]},{t="widget",w="order"},{t="p",s="notice",x="If enemies often spot you before you can open, take Master of Deception instead of Camouflage; it also helps with the level 20 poison quest. The 20–30 talents mostly unlock Hemorrhage, so you can level with another build and respec at 30. Shadowstep is not in the Forever trees."},{t="anchor",id="stats"},{t="kicker",x=S[480]},{t="h2",x=S[385]},{t="p",x="Subtlety wants a high-damage weapon first: Hemorrhage, Ambush and Backstab scale with it. Expertise and hit come next, so your openers land."},{t="h3",x=S[578]},{t="stat",i=1,b=S[439],x="a slow weapon, plus a dagger for Ambush"},{t="stat",i=2,b="Agility",x=S[357]},{t="stat",i=3,b="Stamina",x=""},{t="stat",i=4,b="Strength",x=S[636]},{t="p",s="small",x="A slow weapon beats a fast one with similar damage per second. Raw attack power beats Agility when there is more than twice as much of it."},{t="h3",x="At level 60"},{t="stat",i=1,b=S[439],x=""},{t="stat",i=2,b="Expertise",x="to 6.5%"},{t="stat",i=3,b="Hit chance",x="to 8%"},{t="stat",i=4,b="Weapon skill",x=""},{t="stat",i=5,b="Agility",x=""},{t="p",s="small",x="Hit above 8% keeps helping poisons, which use the 17% spell hit cap and matter more in Forever."},{t="p",s="notice",x=S[49]},{t="anchor",id="combat"},{t="kicker",x=S[386]},{t="h2",x=S[432]},{t="p",x="Treat this as a priority list, not a fixed loop. Ambush arrives at 18, Premeditation and Shank at 24, Ghostly Strike at 25, Hemorrhage at 30 and Death Mark at 54 in this order."},{t="h4",x="Poisons and Stealth"},{t="p",x="From 20 keep Instant Poison on both weapons. Stealth gives little before 18; until then you can open with Backstab from behind."},{t="h4",x="Open"},{t="p",x="Ambush from Stealth with a dagger in your main hand, once learned at 18. Premeditation adds two combo points first; in groups give the tank a few seconds to build threat."},{t="h4",x=S[481]},{t="p",x="Hemorrhage from 30 with any weapon and from any side. Before that, Backstab from behind (Gouge, then step behind) or Sinister Strike from the front, preferably with a slow weapon."},{t="h4",x="Finishers"},{t="p",x="Slice and Dice is your usual finisher unless the enemy is nearly dead, then Eviscerate. From 30, Rupture on enemies that live its full duration: armor does not reduce it, and Hemorrhage makes it and Garrote 15% stronger. From 49, Boot Knife makes Shank add 2 combo points, so use Shank on cooldown; from 54, use Death Mark on a target that will live another 6 seconds, ideally with Garrote and Rupture ticking."},{t="h4",x="Threat and defense"},{t="p",x="Your burst can pull enemies off the tank: Evasion to survive (Setup adds combo points when you dodge) or Vanish to drop threat. Preparation resets Evasion and Vanish for a second use."},{t="h4",x="Control"},{t="p",x="Sap, Gouge and Blind enemies to control a pull or to bandage. Rogues have no area damage, so kill the most dangerous enemy first."},{t="abil",names={"Hemorrhage","Ambush","Backstab",S[601],S[579],"Eviscerate","Rupture","Preparation","Gouge"}},{t="h3",x=S[464]},{t="p",x="Priority: weapon damage and a slow speed first (a 2.8-speed weapon at 14 damage per second beats a 1.9-speed one at 15), then hit, Agility, attack power, critical strike and Strength. Raw attack power is better than Agility when it is more than twice as much."},{t="p",x="Keep a dagger for Ambush and Backstab. Before Hemorrhage, swap between a dagger and a slow weapon with macros; Hemorrhage works with any weapon. Horde Rogues can get Hammer of Orgrimmar early from a quest leading into Ragefire Chasm."},{t="h3",x=S[387]},{t="p",x="The poison quest at 20 needs Stealth, Sap and Pick Pocket, and the Alliance chest is guarded by Klaven Mortwake, a level 26 elite; come back at 22–23 if needed. Raise Lockpicking to 70 (Alliance) or 80 (Horde) first."},{t="p",x="Keep food, potions and bandages: Rogues dodge a lot but have low armor and health. Herbalism pairs well with Sap and Vanish, and Engineering adds grenades for PvP."},{t="anchor",id="macros"},{t="kicker",x=S[508]},{t="h2",x=S[307]},{t="p",x=S[61]},{t="p",s="notice",x=S[53]},{t="macro",n=S[345],x=S[201],code=S[276]},{t="macro",n=S[358],x=S[143],code=S[233]},{t="macro",n=S[580],x=S[189],code=S[219]},{t="macro",n=S[561],x=S[127],code=S[203]},{t="macro",n=S[599],x=S[155],code=S[206]},{t="macro",n=S[562],x=S[139],code=S[218]},{t="macro",n="Vanish",x=S[181],code=S[278]},{t="macro",n=S[417],x=S[137],code=S[269]},{t="macro",n=S[330],x=S[157],code=S[241]},{t="macro",n="Hemorrhage with auto-attack",x="Starts auto-attack and uses Hemorrhage, your builder from 30. Not tested in game.",code="#showtooltip Hemorrhage\n/startattack [harm,nodead]\n/cast [harm,nodead] Hemorrhage"},{t="macro",n="Premeditation and Ambush",x="Adds two combo points with Premeditation, then opens with Ambush.",code="#showtooltip\n/cast Premeditation\n/cast Ambush"},{t="macro",n="Ambush with a weapon swap",x="Before Hemorrhage: equips your dagger in the main hand and the slow weapon in the off hand, then Ambushes. Press it twice; the swap uses a global cooldown. Replace the names.",code="#showtooltip Ambush\n/equipslot 16 Dagger Weapon Name\n/equipslot 17 Slow Weapon Name\n/cast Ambush"},{t="macro",n="Sinister Strike with a weapon swap",x="Swaps the slow weapon back to the main hand and uses Sinister Strike. Swapping resets your swing timer. Replace the names.",code="#showtooltip Sinister Strike\n/startattack\n/equipslot 16 Slow Weapon Name\n/equipslot 17 Dagger Weapon Name\n/cast Sinister Strike"},{t="p",s="small",x=S[220]},{t="anchor",id="dungeons"},{t="kicker",x=S[563]},{t="h2",x=S[346]},{t="p",x=S[69]},{t="widget",w="rarity"},{t="p",s="notice",x=S[70]},{t="p",s="notice",x=S[35]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[388]},{t="h2",x=S[343]},{t="p",x=S[83]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[418]},{t="h2",x=S[331]},{t="p",x=S[32]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[389]},{t="h2",x=S[303]},{t="p",x=S[28]},{t="widget",w="quest"},{t="anchor",id=S[356]},{t="kicker",x=S[564]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[104]}},dungeons={{n=S[282],lr="13–18",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={},t={},no={S[20],S[66],S[12]}}},{n=S[247],lr="13–18",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={},t={},no={S[20],S[66],S[12]}}},{n=S[242],lr="15–20",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={{n=S[509],st=S[30],no=S[37],it={}}},t={},no={S[36],S[23],S[12]}}},{n=S[222],lr="17–24",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={{n=S[448],st=S[30],no=S[37],it={}}},t={{id=10413,n=S[339],mob=S[510],st=S[212],no=S[103]}},no={S[36],S[66],S[12]}}},{n=S[194],lr="17–26",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={{n=S[483],st=S[30],no=S[109],it={{id=5444,n=S[529]}}}},t={{id=1951,n=S[470],mob=S[17],st=S[22],no=S[9]}},no={S[36],S[23],S[12]}}},{n=S[196],lr="22–30",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={{n=S[482],st=S[30],no=S[37],it={}},{n="Gefell",st=S[30],no=S[37],it={}},{n="Gemela",st=S[30],no=S[37],it={}}},t={{id=1482,n="Shadowfang",mob=S[17],st=S[22],no=S[9]},{id=1483,n=S[622],mob=S[17],st=S[22],no=S[9]},{id=1935,n=S[441],mob=S[17],st=S[22],no=S[9]},{id=2807,n=S[571],mob=S[17],st=S[22],no=S[9]}},no={S[36],S[23],S[12]}}},{n=S[302],lr="24–32",st=S[41],no=S[6],ba=true,ra={ck=S[65],r={{n=S[381],s